<script setup lang="ts">
import {computed,ref,watch,onMounted,onBeforeUnmount} from 'vue';
import type {Row} from './api';
const props=withDefaults(defineProps<{data:Row[];series:{key:string;label:string;color:string}[];kind?:'bars'|'line'|'donut';label?:string;title:string;height?:number}>(),{kind:'bars',label:'day',height:230});
const canvas=ref<HTMLCanvasElement>(),host=ref<HTMLDivElement>(),hover=ref<number|null>(null),point=ref({left:0,top:0});
let observer:ResizeObserver|undefined,geometry={left:44,top:14,width:0,height:0};
const populated=computed(()=>props.data.some(row=>props.series.some(s=>Number(row[s.key])>0)));
const tooltip=computed(()=>hover.value===null?null:props.data[hover.value]);
function render(){const element=canvas.value;if(!element||!populated.value)return;const box=element.getBoundingClientRect();if(box.width<1||box.height<1)return;const ratio=Math.min(devicePixelRatio||1,2);element.width=Math.round(box.width*ratio);element.height=Math.round(box.height*ratio);const c=element.getContext('2d');if(!c)return;c.scale(ratio,ratio);const width=box.width,height=box.height;c.font='12px -apple-system,BlinkMacSystemFont,"Microsoft YaHei",sans-serif';
 if(props.kind==='donut'){const total=props.data.reduce((sum,row)=>sum+Number(row.value||0),0),radius=Math.min(width,height)*.34;let start=-Math.PI/2;props.data.forEach((row,index)=>{const value=Number(row.value||0);if(!value||!total)return;const angle=value/total*Math.PI*2;c.beginPath();c.arc(width/2,height/2,radius,start,start+angle);c.lineWidth=19;c.strokeStyle=props.series[index]?.color||'#12a594';c.stroke();start+=angle});c.textAlign='center';c.fillStyle='#1c2024';c.font='600 28px -apple-system,BlinkMacSystemFont,sans-serif';c.fillText(total.toLocaleString(),width/2,height/2+6);c.fillStyle='#8b8d98';c.font='12px -apple-system,BlinkMacSystemFont,"Microsoft YaHei",sans-serif';c.fillText('请求总数',width/2,height/2+29);return}
 const max=Math.max(1,...props.data.map(row=>Math.max(...props.series.map(s=>Number(row[s.key])||0))));const scale=Math.ceil(max/4)||1,ceiling=scale*4;geometry={left:44,top:14,width:width-56,height:height-48};const g=geometry,step=g.width/Math.max(1,props.data.length);
 c.strokeStyle='#e8e8ec';c.lineWidth=.5;c.fillStyle='#8b8d98';c.textAlign='right';for(let i=0;i<=4;i++){const y=g.top+g.height-g.height*i/4;c.beginPath();c.moveTo(g.left,y);c.lineTo(g.left+g.width,y);c.stroke();c.fillText((ceiling*i/4).toLocaleString(),g.left-10,y+4)}
 if(hover.value!==null){c.fillStyle='#e0f8f380';c.fillRect(g.left+hover.value*step,g.top,step,g.height)}c.textAlign='center';const every=Math.max(1,Math.ceil(props.data.length/10));props.data.forEach((row,i)=>{if(i%every===0||i===props.data.length-1)c.fillText(String(row[props.label]).slice(-5),g.left+(i+.5)*step,g.top+g.height+24)});
 props.series.forEach((series,sIndex)=>{if(props.kind==='line'){const points=props.data.map((row,i)=>({x:g.left+(i+.5)*step,y:g.top+g.height-(Number(row[series.key])||0)/ceiling*g.height}));c.beginPath();points.forEach((p,i)=>i?c.lineTo(p.x,p.y):c.moveTo(p.x,p.y));c.strokeStyle=series.color;c.lineWidth=1.6;c.stroke();c.lineTo(points[points.length-1].x,g.top+g.height);c.lineTo(points[0].x,g.top+g.height);c.closePath();c.fillStyle=series.color+'0D';c.fill();if(hover.value!==null){const p=points[hover.value];if(p){c.beginPath();c.arc(p.x,p.y,3,0,Math.PI*2);c.fillStyle=series.color;c.fill()}}}else{const bar=Math.min(13,step*.65/props.series.length);props.data.forEach((row,i)=>{const value=Number(row[series.key])||0;if(value<=0)return;const h=value/ceiling*g.height,x=g.left+(i+.5)*step-(props.series.length*bar)/2+sIndex*bar;c.fillStyle=series.color;c.fillRect(x,g.top+g.height-h,Math.max(1,bar-1.5),h)})}})
}
function track(event:MouseEvent){if(props.kind==='donut')return;const bounds=canvas.value?.getBoundingClientRect();if(!bounds)return;const index=Math.max(0,Math.min(props.data.length-1,Math.floor((event.clientX-bounds.left-geometry.left)/(geometry.width/props.data.length))));hover.value=index;point.value={left:Math.max(4,Math.min(bounds.width-170,event.clientX-bounds.left+12)),top:Math.max(3,Math.min(bounds.height-100,event.clientY-bounds.top-40))}}
function keyboard(event:KeyboardEvent){if(!['ArrowLeft','ArrowRight','Escape'].includes(event.key))return;event.preventDefault();if(event.key==='Escape')hover.value=null;else{hover.value=Math.max(0,Math.min(props.data.length-1,(hover.value??0)+(event.key==='ArrowRight'?1:-1)));point.value={left:Math.max(0,(host.value?.clientWidth||300)-178),top:10}}}
watch([()=>props.data,()=>props.series,()=>props.kind,hover],render,{deep:true,flush:'post'});
onMounted(()=>{observer=new ResizeObserver(render);if(host.value)observer.observe(host.value);render()});onBeforeUnmount(()=>observer?.disconnect());
</script>
<template><div ref="host" class="dg-chart" :style="{height:height+'px'}" :tabindex="populated&&kind!=='donut'?0:undefined" @keydown="keyboard"><canvas v-if="populated" ref="canvas" :style="{height:height+'px'}" role="img" :aria-label="title" @mousemove="track" @mouseleave="hover=null"/><div v-else class="dg-chart-empty">暂无记录</div><div v-if="tooltip&&kind!=='donut'" class="dg-chart-tooltip" :style="{left:point.left+'px',top:point.top+'px'}"><div>{{tooltip[label]}}</div><p v-for="s in series" :key="s.key"><span><i :style="{background:s.color}"/>{{s.label}}</span><strong>{{Number(tooltip[s.key]||0).toLocaleString()}}</strong></p></div></div></template>
